import{_ as d,o as t,c as o,a2 as a}from"./chunks/framework.BUS5y9ZA.js";const b=JSON.parse('{"title":"올바름 인력관리시스템 디자인 가이드","description":"","frontmatter":{},"headers":[],"relativePath":"design-guide.md","filePath":"design-guide.md"}'),l={name:"design-guide.md"};function i(c,e,r,n,h,s){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="올바름-인력관리시스템-디자인-가이드" tabindex="-1">올바름 인력관리시스템 디자인 가이드 <a class="header-anchor" href="#올바름-인력관리시스템-디자인-가이드" aria-label="Permalink to &quot;올바름 인력관리시스템 디자인 가이드&quot;">​</a></h1><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>문서 유형</td><td>전사 공통 디자인 시스템 및 화면 설계 가이드</td></tr><tr><td>대상</td><td>회사소개 홈페이지, 관리자 웹, 현장 근무자 모바일 웹</td></tr><tr><td>디자인 기반</td><td>shadcn/ui <code>new-york</code> 스타일</td></tr><tr><td>기술 기준</td><td>Tailwind CSS v4, Radix UI, Lucide Icons, CSS Custom Properties</td></tr><tr><td>구현 기준</td><td><code>components.json</code>, <code>src/components/ui</code>, <code>src/app/globals.css</code></td></tr><tr><td>기준 문서</td><td>요구사항분석서, 기능명세서, 화면명세서</td></tr></tbody></table><h2 id="_1-프로젝트-디자인-기반" tabindex="-1">1. 프로젝트 디자인 기반 <a class="header-anchor" href="#_1-프로젝트-디자인-기반" aria-label="Permalink to &quot;1. 프로젝트 디자인 기반&quot;">​</a></h2><p>올바름 인력관리시스템의 모든 사용자 화면은 <strong>shadcn/ui를 기본 디자인 시스템으로 사용한다.</strong> 이 기준은 관리자 화면에만 한정하지 않으며 회사소개 홈페이지, 관리자 웹, 현장 근무자 모바일 웹, 인증·설치·오프라인 화면을 포함한 프로젝트 전체에 적용한다.</p><ul><li>shadcn/ui는 Radix UI 기반의 <code>new-york</code> 스타일을 사용한다.</li><li>신규 화면과 개편 화면은 <code>Button</code>, <code>Card</code>, <code>Table</code>, <code>Badge</code>, <code>Alert</code>, <code>Dialog</code>, <code>Sheet</code>, <code>Tooltip</code>, <code>Separator</code>, <code>Skeleton</code>, <code>Input</code> 등 shadcn/ui 컴포넌트를 우선 사용한다.</li><li>shadcn/ui 컴포넌트 소스는 <code>src/components/ui</code>에서 프로젝트가 직접 소유하고 관리한다.</li><li>shadcn 설정은 루트의 <code>components.json</code>을 단일 기준으로 사용한다.</li><li>기반 표면과 상태 표현은 <code>background</code>, <code>foreground</code>, <code>card</code>, <code>muted</code>, <code>primary</code>, <code>border</code>, <code>ring</code>, <code>destructive</code> 등의 의미 기반 토큰을 사용한다.</li><li>조건부 클래스 결합에는 <code>src/lib/utils.ts</code>의 <code>cn()</code>을 사용한다.</li><li>아이콘은 Lucide Icons를 기본으로 사용하며 한 화면에서 크기와 선 굵기를 일관되게 유지한다.</li><li>기존 레거시 화면은 기능을 보존하면서 shadcn/ui 기반 컴포넌트로 단계적으로 전환한다.</li><li>공통 컴포넌트가 있는 경우 동일한 버튼·입력창·카드·표·모달을 화면별로 다시 구현하지 않는다.</li></ul><h2 id="_2-디자인-원칙" tabindex="-1">2. 디자인 원칙 <a class="header-anchor" href="#_2-디자인-원칙" aria-label="Permalink to &quot;2. 디자인 원칙&quot;">​</a></h2><ul><li>업무 정보를 빠르게 찾을 수 있도록 명확하고 일관된 화면을 제공한다.</li><li>관리자 화면은 목록·검색·입력 중심으로, 현장 근무자 화면은 한 손 조작이 쉬운 모바일 중심으로 설계한다.</li><li>장식보다 정보 위계, 충분한 여백, 읽기 쉬운 대비를 우선한다.</li><li>색상만으로 상태를 구분하지 않고 상태명과 안내 문구를 함께 제공한다.</li><li>PC와 모바일에서 동일한 업무 의미와 용어를 유지한다.</li><li>shadcn/ui 기본 동작과 접근성을 유지하고, 업무별 차이는 속성·variant·조합 컴포넌트로 표현한다.</li><li>디자인 변경이 인증, 권한, API 계약, 업무 규칙을 변경하지 않도록 시각 컴포넌트와 업무 로직을 분리한다.</li></ul><h2 id="_3-색상" tabindex="-1">3. 색상 <a class="header-anchor" href="#_3-색상" aria-label="Permalink to &quot;3. 색상&quot;">​</a></h2><table tabindex="0"><thead><tr><th>용도</th><th>기준</th></tr></thead><tbody><tr><td>Primary</td><td>주요 버튼, 활성 메뉴, 핵심 강조에 사용</td></tr><tr><td>Canvas</td><td>페이지 기본 배경</td></tr><tr><td>Surface</td><td>카드, 입력 영역, 표 배경</td></tr><tr><td>Ink</td><td>제목과 본문 기본 글자</td></tr><tr><td>Muted</td><td>설명, 보조 정보, 비활성 정보</td></tr><tr><td>Hairline</td><td>표와 입력창의 경계선</td></tr><tr><td>Success/Warning/Error</td><td>처리 결과와 주의·오류 상태</td></tr></tbody></table><ul><li>실제 색상값은 <code>src/app/globals.css</code>의 디자인 토큰을 우선 적용한다.</li><li>컴포넌트에 임의 색상을 추가하기보다 공통 토큰을 확장한다.</li></ul><h3 id="_3-1-올바름-전용-pantone-색상" tabindex="-1">3.1 올바름 전용 Pantone 색상 <a class="header-anchor" href="#_3-1-올바름-전용-pantone-색상" aria-label="Permalink to &quot;3.1 올바름 전용 Pantone 색상&quot;">​</a></h3><p>올바름의 공식 전용색상은 다음 네 가지 Pantone CMYK Coated 색상을 원본 식별자로 사용한다.</p><table tabindex="0"><thead><tr><th>원본 식별자</th><th>공식 sRGB/HEX</th><th>시스템 직군</th></tr></thead><tbody><tr><td><code>PANTONE P 115-6 C</code></td><td>Pantone Connect 확인 후 기록</td><td>명도·대비 분석 후 확정</td></tr><tr><td><code>PANTONE P 115-16 C</code></td><td>Pantone Connect 확인 후 기록</td><td>명도·대비 분석 후 확정</td></tr><tr><td><code>PANTONE P 106-16 C</code></td><td>Pantone Connect 확인 후 기록</td><td>명도·대비 분석 후 확정</td></tr><tr><td><code>PANTONE P 169-15 C</code></td><td>Pantone Connect 확인 후 기록</td><td>명도·대비 분석 후 확정</td></tr></tbody></table><ul><li>Pantone 식별자는 인쇄 원본을 관리하기 위한 값이며 CSS 색상값으로 직접 사용하지 않는다.</li><li>웹과 앱에는 Pantone Connect의 <code>COLOR DATA</code>에서 확인한 공식 sRGB/HEX 값을 사용한다. 임의 변환 사이트의 근사값을 브랜드 원색으로 확정하지 않는다.</li><li>공식 HEX 확보 후 상대 명도와 WCAG 대비를 계산해 <code>Primary</code>, <code>Secondary</code>, <code>Accent</code>, <code>Brand Dark</code> 직군을 배정한다.</li><li>공식 HEX가 확정되기 전까지 현재의 파란색 <code>primary</code> 토큰을 임시 디지털 기준색으로 유지한다.</li><li>hover, active, muted, foreground 색상은 공식 원색에서 파생하되 텍스트와 아이콘은 WCAG AA 대비를 충족해야 한다.</li><li>Pantone 원색은 <code>--brand-pantone-*</code> 원시 토큰으로 보존하고, 화면에서는 <code>primary</code>, <code>secondary</code>, <code>accent</code>, <code>foreground</code> 같은 의미 기반 토큰만 사용한다.</li><li>버튼, Badge, Chart, Alert 등에 Pantone HEX를 직접 작성하지 않는다. 공통 토큰을 변경하면 시스템 전체에 동일하게 반영되도록 한다.</li><li>인쇄물은 Pantone 실물 가이드와 출력 조건을 기준으로 별도 검수하며, 모니터 표시색과 인쇄 결과가 완전히 동일하다고 가정하지 않는다.</li></ul><h2 id="_4-타이포그래피" tabindex="-1">4. 타이포그래피 <a class="header-anchor" href="#_4-타이포그래피" aria-label="Permalink to &quot;4. 타이포그래피&quot;">​</a></h2><ul><li>기본 글꼴은 Pretendard 계열을 사용한다.</li><li>페이지 제목은 32~40px, 섹션 제목은 20~24px, 본문은 15~17px를 권장한다.</li><li>입력 라벨과 표 머리글은 본문보다 작게 사용하되 12px 미만으로 축소하지 않는다.</li><li>제목, 버튼, 입력 라벨은 동일 화면에서 동일한 굵기 체계를 유지한다.</li></ul><h2 id="_5-레이아웃" tabindex="-1">5. 레이아웃 <a class="header-anchor" href="#_5-레이아웃" aria-label="Permalink to &quot;5. 레이아웃&quot;">​</a></h2><h3 id="_5-1-관리자-화면" tabindex="-1">5.1 관리자 화면 <a class="header-anchor" href="#_5-1-관리자-화면" aria-label="Permalink to &quot;5.1 관리자 화면&quot;">​</a></h3><ul><li>PC에서는 좌측 사이드바와 본문 영역을 사용하고, 모바일에서는 햄버거 메뉴로 전환한다.</li><li>본문 최대 폭은 업무 화면 특성에 따라 980~1180px를 기준으로 한다.</li><li>목록 화면은 제목, 조회 조건, 주요 작업, 결과 목록 순으로 구성한다.</li><li>공통 쉘은 shadcn <code>Sidebar</code>, <code>Sheet</code>, <code>Tooltip</code>, <code>Separator</code>를 조합해 구성한다.</li><li>대시보드와 업무 화면은 shadcn <code>Card</code>, <code>Table</code>, <code>Badge</code>, <code>Alert</code>, <code>Skeleton</code>을 기본 구성 요소로 사용한다.</li></ul><h3 id="_5-2-현장-근무자-화면" tabindex="-1">5.2 현장 근무자 화면 <a class="header-anchor" href="#_5-2-현장-근무자-화면" aria-label="Permalink to &quot;5.2 현장 근무자 화면&quot;">​</a></h3><ul><li>세로형 모바일 화면을 우선하며 주요 버튼은 충분한 터치 영역과 전체 폭을 확보한다.</li><li>위치·카메라·알림 등 권한이 필요한 기능은 요청 목적과 거부 시 대안을 안내한다.</li><li>처리 중에는 로딩 상태를 표시하고 중복 입력을 방지한다.</li></ul><h3 id="_5-3-회사소개-홈페이지" tabindex="-1">5.3 회사소개 홈페이지 <a class="header-anchor" href="#_5-3-회사소개-홈페이지" aria-label="Permalink to &quot;5.3 회사소개 홈페이지&quot;">​</a></h3><ul><li>대표 이미지와 핵심 메시지, 서비스 강점, 사회적 가치, 상담 신청, 회사 정보 순으로 구성한다.</li><li>카드 영역은 모바일 1열, 넓은 화면 3열을 기본으로 한다.</li></ul><h3 id="_5-4-모바일-목록형-데이터" tabindex="-1">5.4 모바일 목록형 데이터 <a class="header-anchor" href="#_5-4-모바일-목록형-데이터" aria-label="Permalink to &quot;5.4 모바일 목록형 데이터&quot;">​</a></h3><ul><li>관리자 웹, 현장 근무자 웹, 회사소개 및 기타 사용자 화면의 <strong>모든 목록형 데이터는 768px 미만 모바일 화면에서 공통적으로 카드 형태로 표시한다.</strong></li><li>데스크톱과 태블릿에서는 shadcn <code>Table</code>의 행·열 구조를 유지하고, 모바일에서는 한 개의 데이터 행을 한 개의 독립된 <code>Card</code> 단위로 전환한다.</li><li>모바일 카드 안에서는 각 값의 항목명을 <code>data-label</code>로 함께 표시해 데스크톱 표 머리글과 동일한 의미를 유지한다.</li><li>카드 간에는 명확한 간격을 두고 <code>card</code>, <code>border</code>, <code>muted-foreground</code> 등 의미 기반 토큰을 사용한다.</li><li>긴 텍스트, 상태 Badge, 링크와 작업 버튼은 카드 너비 안에서 줄바꿈되며 화면 밖으로 잘리지 않아야 한다.</li><li>빈 목록은 빈 카드를 반복하지 않고 목록 영역 전체를 사용하는 하나의 명확한 empty state로 표시한다.</li><li>단일 열 목록은 중복된 항목명을 표시하지 않고 콘텐츠 자체를 카드 본문으로 사용한다.</li><li>모바일 목록의 기본 표현을 가로 스크롤 테이블로 대체하지 않는다. 비교를 위해 가로축 유지가 필수인 비목록형 매트릭스·일정표·차트만 별도 설계한다.</li><li>이 동작은 화면별 CSS가 아니라 <code>src/components/ui/table.tsx</code>와 공통 반응형 스타일에서 관리한다.</li></ul><h2 id="_6-공통-컴포넌트" tabindex="-1">6. 공통 컴포넌트 <a class="header-anchor" href="#_6-공통-컴포넌트" aria-label="Permalink to &quot;6. 공통 컴포넌트&quot;">​</a></h2><table tabindex="0"><thead><tr><th>컴포넌트</th><th>적용 기준</th></tr></thead><tbody><tr><td><code>Button</code></td><td>저장·등록·실행 등 주요 동작에 사용하며 배경색과 글자색이 함께 정의된 variant를 명시적으로 선택한다.</td></tr><tr><td><code>Card</code></td><td>요약 정보, 차트, 표, 입력 그룹처럼 독립된 정보 단위에 사용한다.</td></tr><tr><td><code>Input</code> / <code>Textarea</code></td><td>연결된 라벨, 필수 여부, 도움말, 오류 문구와 함께 사용한다.</td></tr><tr><td><code>Table</code></td><td>구조화된 업무 목록에 사용하고 머리글, 빈 상태를 제공하며 모바일에서는 행 단위 Card로 전환한다.</td></tr><tr><td><code>Badge</code></td><td>완료·미완료, 출근·퇴근, 활성·비활성처럼 짧은 상태에 사용한다.</td></tr><tr><td><code>Alert</code></td><td>성공·경고·오류·중요 안내를 제목과 설명으로 제공한다.</td></tr><tr><td><code>Dialog</code></td><td>현재 흐름을 유지해야 하는 입력·안내에 사용한다.</td></tr><tr><td><code>AlertDialog</code></td><td>삭제 등 복구가 어려운 동작의 최종 확인에 사용한다.</td></tr><tr><td><code>Sheet</code></td><td>모바일 메뉴, 필터, 보조 작업 패널에 사용한다.</td></tr><tr><td><code>Skeleton</code></td><td>실제 콘텐츠 구조를 반영한 로딩 상태에 사용한다.</td></tr></tbody></table><h3 id="_6-1-버튼-variant와-색상-대비" tabindex="-1">6.1 버튼 variant와 색상 대비 <a class="header-anchor" href="#_6-1-버튼-variant와-색상-대비" aria-label="Permalink to &quot;6.1 버튼 variant와 색상 대비&quot;">​</a></h3><ul><li>shadcn/ui <code>Button</code>의 기본 variant는 <code>bg-primary</code>와 <code>text-primary-foreground</code>를 하나의 시각 계약으로 제공한다. 기본 variant에서 배경만 <code>bg-background</code>, <code>bg-white</code>, <code>bg-muted</code>, <code>bg-secondary</code>, <code>bg-transparent</code> 등으로 덮어쓰지 않는다. 배경만 밝게 바꾸면 기본의 밝은 글자색이 남아 버튼 문구가 보이지 않을 수 있다.</li><li>주요 실행 동작은 <code>default</code>, 밝은 배경의 보조 동작은 <code>outline</code>, 조용한 아이콘·도구 동작은 <code>ghost</code>, 텍스트형 이동은 <code>link</code>, 위험 동작은 <code>destructive</code>를 사용한다.</li><li><code>className</code>은 너비, 간격, 정렬처럼 variant가 제공하지 않는 레이아웃 조정에 우선 사용한다. 배경색·글자색·테두리를 조합해 기존 variant를 화면마다 다시 만들지 않는다.</li><li>링크를 버튼처럼 표시할 때도 <code>Button asChild</code>에 용도에 맞는 variant를 명시한다.</li><li>기본, hover, focus, disabled 상태 모두에서 텍스트와 배경은 WCAG AA 수준의 대비를 유지한다.</li><li>시스템 전역 회귀 테스트는 밝은 배경이나 입력형 테두리를 직접 지정한 <code>Button</code>에 명시적 variant가 있는지 검사한다.</li></ul><h2 id="_7-접근성-및-반응형" tabindex="-1">7. 접근성 및 반응형 <a class="header-anchor" href="#_7-접근성-및-반응형" aria-label="Permalink to &quot;7. 접근성 및 반응형&quot;">​</a></h2><ul><li>모든 입력 요소에 연결된 라벨을 제공한다.</li><li>키보드 포커스를 시각적으로 표시하고 버튼과 링크를 키보드로 실행할 수 있게 한다.</li><li>텍스트와 배경은 WCAG AA 수준의 대비를 목표로 한다.</li><li>모바일의 목록형 표는 행 단위 카드로 전환하고 각 값에 항목명을 함께 표시한다.</li><li>이미지에는 용도를 설명하는 대체 텍스트를 제공한다.</li></ul><h2 id="_8-변경-관리" tabindex="-1">8. 변경 관리 <a class="header-anchor" href="#_8-변경-관리" aria-label="Permalink to &quot;8. 변경 관리&quot;">​</a></h2><ul><li>공통 토큰이나 컴포넌트 변경 시 관리자·근무자·회사소개 화면의 영향을 함께 확인한다.</li><li>신규 화면은 <code>화면명세서.md</code>에 화면 ID와 동작을 먼저 반영한다.</li><li>구현 검수 시 PC, 모바일, 키보드 조작, 권한 거부 상태를 포함한다.</li><li>신규 UI는 shadcn/ui 적용을 기본 완료 조건으로 검토한다.</li><li>필요한 컴포넌트만 프로젝트에 추가하고 예제 블록의 샘플 데이터나 불필요한 의존성을 포함하지 않는다.</li><li><code>src/components/ui</code>의 공통 컴포넌트를 수정할 때는 기존 관리자·근로자·공개 화면의 회귀 테스트를 함께 수행한다.</li><li>레거시 스타일과 shadcn/ui가 전환 기간 동안 공존할 수 있으나, 하나의 화면 안에서는 동일한 밀도·모서리·상태 표현 체계를 유지한다.</li></ul><h2 id="_9-시스템-전체-shadcn-ui-new-york-전면-개편-계획" tabindex="-1">9. 시스템 전체 shadcn/ui new-york 전면 개편 계획 <a class="header-anchor" href="#_9-시스템-전체-shadcn-ui-new-york-전면-개편-계획" aria-label="Permalink to &quot;9. 시스템 전체 shadcn/ui new-york 전면 개편 계획&quot;">​</a></h2><h3 id="_9-1-공통-기반" tabindex="-1">9.1 공통 기반 <a class="header-anchor" href="#_9-1-공통-기반" aria-label="Permalink to &quot;9.1 공통 기반&quot;">​</a></h3><ul><li>기존 <code>components.json</code>의 Radix 기반 <code>new-york</code> 설정을 단일 기준으로 유지한다.</li><li>화면에서 실제로 필요한 shadcn/ui 컴포넌트만 추가하고 예제 데이터와 불필요한 의존성을 포함하지 않는다.</li><li>공통 페이지 헤더, 조회 조건, 데이터 표, 폼 필드, 상태 Badge, 로딩·오류·빈 상태를 조합 컴포넌트로 표준화한다.</li><li>자체 모달과 삭제 확인은 각각 <code>Dialog</code>, <code>AlertDialog</code> 기반으로 교체한다.</li><li>레거시 색상과 임의 HEX를 의미 기반 토큰으로 전환하되 공식 Pantone HEX가 확정될 때까지 현재 파란색을 임시 <code>primary</code>로 사용한다.</li></ul><h3 id="_9-2-관리자-웹" tabindex="-1">9.2 관리자 웹 <a class="header-anchor" href="#_9-2-관리자-웹" aria-label="Permalink to &quot;9.2 관리자 웹&quot;">​</a></h3><ul><li>기존 Sidebar, 모바일 Sheet, Header, Dashboard를 관리자 화면의 표준 쉘로 유지한다.</li><li>목록은 <code>PageHeader → 조회 조건 Card → Table</code>, 등록·수정은 <code>PageHeader → Form Card → 작업 버튼</code>, 상세는 핵심 정보와 관련 데이터 Card 순서로 통일한다.</li><li>로딩은 콘텐츠 형태의 Skeleton, 오류는 Alert, 상태는 Badge, 삭제는 AlertDialog로 표현한다.</li><li>잘못 표기된 <code>/manager/safety/*</code>는 <code>/manager/safety/*</code>로 정리하고 기존 URL은 영구 리다이렉트로 호환한다.</li><li>API, 인증, 엑셀, QR/NFC, 교육과 알림의 업무 계약은 변경하지 않는다.</li></ul><h3 id="_9-3-현장-근로자-앱" tabindex="-1">9.3 현장 근로자 앱 <a class="header-anchor" href="#_9-3-현장-근로자-앱" aria-label="Permalink to &quot;9.3 현장 근로자 앱&quot;">​</a></h3><ul><li><code>/guard</code>의 공통 제품 명칭은 “현장 근로자”로 사용하고 경비원·미화원은 실제 직군 Badge로 구분한다.</li><li>모바일 화면은 상단 상태 영역, 본문, 홈·출퇴근·업무·내 정보 하단 탐색으로 구성한다.</li><li>직군별 작업 홈을 제공하고 기존 출퇴근, QR, NFC, 특이사항, 교육, 프로필 딥링크를 유지한다.</li><li>모든 주요 터치 영역은 최소 48px로 구성하고 위치·카메라·NFC·알림 권한의 거부와 미지원 상태에 대안을 제공한다.</li><li>현재의 확대·글자 크기, 세션, 패스키, PWA 설치 동작은 보존한다.</li></ul><h3 id="_9-4-공개·인증·오프라인-화면" tabindex="-1">9.4 공개·인증·오프라인 화면 <a class="header-anchor" href="#_9-4-공개·인증·오프라인-화면" aria-label="Permalink to &quot;9.4 공개·인증·오프라인 화면&quot;">​</a></h3><ul><li>회사소개 홈페이지는 마케팅 정보 구조를 유지하면서 Card, Button, Dialog, Input, Textarea, Progress로 재구성한다.</li><li>관리자 및 현장 근로자 인증은 Card 중심의 일관된 인증 화면으로 구성한다.</li><li>PWA 설치, 인앱 브라우저, 오프라인 안내를 접근 가능한 Dialog, Alert, Button 조합으로 통일한다.</li></ul><h3 id="_9-5-완료-조건" tabindex="-1">9.5 완료 조건 <a class="header-anchor" href="#_9-5-완료-조건" aria-label="Permalink to &quot;9.5 완료 조건&quot;">​</a></h3><ul><li>사용자 화면에서 raw 버튼·입력·선택·표·모달의 중복 구현을 제거하고 shadcn/ui 또는 공통 조합 컴포넌트를 사용한다.</li><li>더 이상 사용하지 않는 <code>.button-primary</code>, <code>.button-secondary</code>, <code>.field</code>, <code>.apple-table</code>, <code>.status-*</code> 레거시 스타일을 제거한다.</li><li><code>npm test</code>, <code>npm run lint</code>, <code>npm run build</code>가 모두 통과해야 한다.</li><li>390px, 768px, 1440px에서 주요 화면을 검수하고 키보드 조작, 포커스, 스크롤, safe-area, 표 오버플로를 확인한다.</li><li>공식 Pantone HEX가 제공되면 토큰 대응표, 대비 결과, 컴포넌트 적용 결과를 본 문서와 <code>globals.css</code>에 함께 반영한다.</li></ul>',44)])])}const p=d(l,[["render",i]]);export{b as __pageData,p as default};
